var s = String(result || '').replace(/\r/g, '');
var out = '';
var i = s.indexOf('小说简介');
if (i < 0) i = s.indexOf('内容简介');
if (i > -1) {
  s = s.substring(i);
  var p = s.indexOf('</p>');
  if (p > -1) s = s.substring(p + 4);
  var ends = ['<div align="center"', '<div class="pageMainArea"', '<script'];
  for (var n = 0; n < ends.length; n++) {
    var j = s.indexOf(ends[n]);
    if (j > -1) s = s.substring(0, j);
  }
  out = s.replace(/<br\s*\/?>/ig, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&raquo;/g, '').replace(/^[\s\n]+/, '').replace(/[\s\n]+$/, '');
}
out;

ruleContent.content:
@js:
var s = String(result || '');
function grab(html) {
  var c = html.indexOf('class="content-box"');
  if (c > -1) { html = html.substring(html.indexOf('>', c) + 1); }
  var b = html.indexOf('下载本书');
  if (b > -1) { html = html.substring(0, b); }
  html = html.replace(/<br\s*\/?>/ig, '\n')
             .replace(/<[^>]+>/g, '')
             .replace(/&nbsp;/g, ' ')
             .replace(/&raquo;/g, '')
             .replace(/&amp;/g, '&')
             .replace(/\ufeff/g, '');
  return html.replace(/^[\s\n]+/, '').replace(/[\s\n]+$/, '');
}
var out;
if (s.substr(0, 2) == 'PK' && s.charCodeAt(2) == 3) {
  out = '【压缩包】本站在该书上架较早，只提供 ZIP 压缩包（无在线阅读页），阅读器无法解压。\n请复制本章链接用浏览器下载后，用「本地导入」阅读：\n' + String(baseUrl);
} else {
  out = grab(s);
  if (out.replace(/\s/g, '').length < 60) {
    var cs = ['gb18030', 'utf-8'];
    for (var i = 0; i < cs.length; i++) {
      try {
        var t = grab(String(java.ajax(String(baseUrl) + ',{"charset":"' + cs[i] + '"}'))); 
        if (t.length > out.length) { out = t; }
      } catch (e) { }
    }
  }
  out = out.replace(/推荐一个小说下载必备网址[^\n]*/g, '')
           .replace(/每天更新，喜欢的去看看。[^\n]*/g, '')
           .replace(/\r/g, '')
           .replace(/\u3000\u3000/g, '\n')
           .replace(/\n{3,}/g, '\n\n')
           .replace(/^[\s\n]+/, '')
           .replace(/[\s\n]+$/, '');
}
result = out;
out;
